(ns armstrong-numbers) (require '[clojure.string :as str]) (defn number-to-list [num] (map read-string (str/split (str num) #""))) (defn exp [x n] (reduce * (repeat n x))) (defn count-digits [num] (count (str num))) (defn exp-every-number [numbers n] (map (fn [x] (exp x n)) numbers)) (defn armstrong? [num] (= num (reduce + (exp-every-number (number-to-list num) (count-digits num)))))
